<script setup lang="ts">
import {onMounted,reactive,ref} from 'vue';
import type {MaterialContext,MaterialFilters,MaterialDetail,MaterialRow,MaterialPage,MaterialHistory} from '../types/materials';
import {materialsApi} from '../api/materials';
import {useReadScope} from '../composables/useReadScope';
import PageHeader from '../components/PageHeader.vue';
import ReadOnlyFacts from '../components/ReadOnlyFacts.vue';
import MaterialPreview from '../components/MaterialPreview.vue';
const props=defineProps<{context:MaterialContext}>(),api=materialsApi(props.context),reads=useReadScope(props.context),saved=props.context.memory.materials;
const filters=reactive<MaterialFilters>({query:'',label:'',annotation_state:'',quality_status:'',storage_source_id:'',source_batch_id:'',created_from:'',created_to:'',...saved?.filters});
const number=ref(saved?.page||1),layout=ref<'grid'|'list'>(saved?.layout||'grid'),selected=ref<string[]>(saved?.selectedItems||[]),page=ref<MaterialPage|null>(null),detail=ref<MaterialDetail|null>(null),drawer=ref(false),showBoxes=ref(true),history=ref<MaterialHistory|null>(null),selectionNote=ref('');
const status:Record<string,string>={unannotated:'未标注',annotated:'已标注',confirmed_empty:'已确认无目标',partial:'标注范围不完整',needs_review:'待审核'};
function remember(){props.context.memory.materials={filters:{...filters},page:number.value,layout:layout.value,selectedItems:[...selected.value]}}
function close(){reads.cancel('detail');reads.cancel('history');drawer.value=false;detail.value=null;history.value=null}
function load(){remember();close();return reads.run('materials',signal=>api.list(filters,number.value,signal),value=>{page.value=value})}
function search(){number.value=1;void load()}
function turn(delta:number){number.value+=delta;void load()}
function choose(id:string,value:boolean){selectionNote.value='';if(value&&!selected.value.includes(id)){if(selected.value.length>=200){selectionNote.value='最多保留 200 张选择，请先清除部分选择';return}selected.value=[...selected.value,id]}if(!value)selected.value=selected.value.filter(x=>x!==id);remember()}
function choosePage(){for(const row of page.value?.items||[])choose(row.id,true)}
function open(row:MaterialRow){close();drawer.value=true;void reads.run('detail',signal=>api.detail(row.id,signal),value=>{detail.value=value})}
function readHistory(targetPage=1){if(!detail.value||!props.context.history)return;const id=detail.value.image.id;void reads.run('history',signal=>props.context.history!(id,targetPage,signal),value=>{history.value=value})}
function legacy(action:'manage'|'upload'|'annotate',id?:string){remember();close();props.context.legacyMaterials?.(action,id)}
onMounted(()=>void load());
</script>
<template><section class="catalog-preview material-library" aria-label="素材库只读浏览"><PageHeader title="素材库" eyebrow="数据管理 / 素材" description="浏览原素材库与正式标注；上传、标注和管理沿用原工作台。" badge="只读" @back="legacy('manage')"/>
<div class="preview-actions"><el-button v-if="context.legacyMaterials" @click="legacy('upload')">上传素材</el-button><el-button v-if="context.openNegativePool" @click="remember();context.openNegativePool()">负样本池</el-button><el-button :disabled="reads.busy.materials" @click="load">刷新素材</el-button></div>
<form class="filters" @submit.prevent="search"><el-input v-model="filters.query" aria-label="素材名称" placeholder="搜索图片名称"/><el-select v-model="filters.annotation_state" aria-label="标注状态"><el-option label="全部标注状态" value=""/><el-option v-for="(label,value) in status" :key="value" :label="label" :value="value"/></el-select><el-button type="primary" native-type="submit" :disabled="reads.busy.materials">查询素材</el-button><details><summary>更多筛选条件</summary><div class="extra-filters"><label>标签编码<el-input v-model="filters.label" placeholder="任一标签编码"/></label><label>来源 ID<el-input v-model="filters.storage_source_id"/></label><label>导入批次<el-input v-model="filters.source_batch_id"/></label><label>质量状态<el-select v-model="filters.quality_status"><el-option label="全部" value=""/><el-option label="未检查" value="pending_decision"/><el-option label="已处理" value="processed"/><el-option label="有问题" value="issue"/></el-select></label><label>起始日期<input v-model="filters.created_from" type="date"></label><label>截止日期<input v-model="filters.created_to" type="date"></label></div></details></form>
<el-alert v-if="reads.errors.materials" :title="reads.errors.materials" type="error" :closable="false"/><p v-if="reads.errors.materials&&page">当前显示上次读取结果，请重试刷新。</p><el-alert v-if="selectionNote" :title="selectionNote" type="warning" :closable="false"/>
<div class="result-tools"><span>{{ page?`共 ${page.total} 张素材`:'正在读取素材' }} · 已选 {{ selected.length }} 张</span><div class="preview-actions"><el-button @click="choosePage" :disabled="!page||reads.busy.materials">选择本页</el-button><el-button @click="selected=[];remember()">清除选择</el-button><el-button :aria-pressed="layout==='grid'" @click="layout='grid';remember()">网格</el-button><el-button :aria-pressed="layout==='list'" @click="layout='list';remember()">列表</el-button><el-checkbox v-model="showBoxes">标注框</el-checkbox></div></div>
<details v-if="selected.length" class="selected-materials"><summary>已选素材摘要 · {{ selected.length }} 张</summary><ul><li v-for="id in selected" :key="id">{{ page?.items.find(row=>row.id===id)?.filename||id }} <el-button link @click="choose(id,false)">移除</el-button></li></ul></details><el-skeleton v-if="!page&&reads.busy.materials" :rows="8" animated/><el-empty v-else-if="page&&!page.items.length" description="当前条件下没有素材"/><div v-if="page" class="material-results" :class="layout" :aria-busy="reads.busy.materials"><article v-for="row in page.items" :key="row.id" class="material-card"><div class="image-button"><MaterialPreview :image="row" :project-id="context.projectId" :boxes="row.annotation_preview" :show-boxes="showBoxes"/></div><div class="card-copy"><el-checkbox :model-value="selected.includes(row.id)" :aria-label="`选择 ${row.filename}`" @change="(value:unknown)=>choose(row.id,!!value)">{{ row.filename }}</el-checkbox><p>{{ status[row.annotation_state||'']||row.annotation_state||'状态未提供' }} · {{ row.box_count??'—' }} 框</p><p>{{ row.width||'—' }} × {{ row.height||'—' }} · {{ row.created_at?.slice(0,10)||'日期未提供' }}</p><p>{{ row.labels?.join('、')||'未提供标签' }}</p><small v-if="(row.box_count||0)>(row.annotation_preview?.length||0)">缩略图显示部分框，详情读取完整标注</small><el-button link type="primary" @click="open(row)">详情</el-button></div></article></div>
<footer v-if="page" class="preview-pagination"><span>第 {{ page.page }} / {{ page.total_pages }} 页 · 每页 {{ page.page_size }} 张</span><div class="preview-actions"><el-button :disabled="number<=1||reads.busy.materials" @click="turn(-1)">上一页</el-button><el-button :disabled="!page.has_next||reads.busy.materials" @click="turn(1)">下一页</el-button></div></footer>
<el-drawer :model-value="drawer" title="素材详情" size="min(960px,100vw)" :append-to-body="false" :lock-scroll="false" :before-close="close"><el-skeleton v-if="reads.busy.detail" :rows="8" animated/><el-alert v-else-if="reads.errors.detail" :title="reads.errors.detail" type="error" :closable="false"/><template v-else-if="detail"><h2>{{ detail.image.filename }}</h2><MaterialPreview :image="detail.image" :project-id="context.projectId" :boxes="detail.annotation.boxes" full/><el-alert v-if="detail.boxes_truncated" :title="`共 ${detail.boxes_total} 框，当前仅展示 ${detail.annotation.boxes.length} 框`" type="warning" :closable="false"/><ReadOnlyFacts :fields="[['标注状态',status[detail.annotation.annotation_state]||detail.annotation.annotation_state],['正式标注框数',detail.boxes_total],['标注版本',detail.annotation.annotation_version],['图片宽度',detail.image.width],['图片高度',detail.image.height],['大小（字节）',detail.image.size_bytes],['来源',detail.image.storage_source_id],['导入批次',detail.image.source_batch_id||detail.image.import_batch_id],['存储类型',detail.image.storage_type],['源文件可用性',detail.image.source_available===true?'后端确认可用':detail.image.source_available===false?'后端确认不可用':'未提供'],['标注异常',detail.image.annotation_issue_type],['创建时间',detail.image.created_at],['质量状态',detail.image.quality_status],['素材 ID',detail.image.id],['SHA256',detail.image.content_sha256]]"/><section v-if="context.history"><h3>历史使用</h3><el-button :loading="reads.busy.history" @click="readHistory()">读取历史使用记录</el-button><el-alert v-if="reads.errors.history" :title="reads.errors.history" type="error" :closable="false"/><div v-if="history"><p>当前历史状态：{{ history.state||'未知' }} · 共 {{ history.total }} 条。未检索到记录不等于从未使用。覆盖范围：{{ history.coverage||'未知' }}</p><el-table :data="history.items" empty-text="未查询到使用记录；历史覆盖范围需以原记录为准"><el-table-column prop="task_id" label="训练任务" min-width="160"/><el-table-column prop="algorithm_name" label="算法"/><el-table-column prop="role" label="样本角色"/><el-table-column prop="status" label="任务状态"/></el-table><div class="preview-actions"><el-button :disabled="history.page<=1||reads.busy.history" @click="readHistory(history.page-1)">上一页历史</el-button><span>第 {{ history.page }} 页</span><el-button :disabled="history.page*history.page_size>=history.total||reads.busy.history" @click="readHistory(history.page+1)">下一页历史</el-button></div></div><p v-else>点击后读取原历史记录。</p></section></template><template #footer><el-button @click="close">返回素材库</el-button><el-button v-if="detail&&context.legacyMaterials" type="primary" @click="legacy('annotate',detail.image.id)">在原工作台标注</el-button></template></el-drawer></section></template>
<style scoped>
.selected-materials{margin:12px 0;font-size:13px}.selected-materials summary{cursor:pointer}.selected-materials ul{max-height:180px;overflow:auto;overflow-wrap:anywhere}.filters{display:flex;flex-wrap:wrap;gap:12px;margin:20px 0;align-items:center}.filters>.el-input{flex:1;min-width:180px}.filters>.el-select{width:190px}.filters details{width:100%;border:1px solid #dce4ef;border-radius:10px;padding:12px}.filters summary{cursor:pointer}.extra-filters{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;padding-top:16px}.extra-filters label{display:grid;gap:6px;color:#475569}.extra-filters input[type=date]{padding:9px;border:1px solid #cbd5e1;border-radius:6px;max-width:100%}.result-tools{display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px;margin:18px 0}.material-results.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:16px}.material-card{border:1px solid #dce4ef;border-radius:14px;overflow:hidden;background:white;min-width:0}.image-button{display:block;border:0;padding:0;width:100%;cursor:pointer;text-align:left;background:transparent}.image-button:focus-visible{outline:3px solid #2563eb;outline-offset:-3px}.card-copy{padding:12px;overflow-wrap:anywhere}.card-copy p{margin:7px 0;color:#64748b;font-size:13px}.card-copy small{color:#64748b}.card-copy .el-checkbox{max-width:100%;height:auto;white-space:normal}.card-copy :deep(.el-checkbox__label){white-space:normal;overflow-wrap:anywhere}.list{display:grid;gap:12px}.list .material-card{display:grid;grid-template-columns:150px 1fr}.history-result{max-height:260px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;background:#f1f5f9;padding:12px;border-radius:8px}@media(max-width:760px){.extra-filters{grid-template-columns:repeat(2,minmax(0,1fr))}.material-results.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.list .material-card{grid-template-columns:100px 1fr}}@media(max-width:420px){.extra-filters{grid-template-columns:1fr}.material-results.grid{grid-template-columns:1fr}}
</style>

